package in.foodcart.api;
import in.foodcart.service.AuthService;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.nio.file.*;import java.util.*;
@RestController @RequestMapping("/api/vendor/uploads") public class VendorUploadController {private final AuthService auth;@Value("${app.upload-dir:uploads}") String directory;public VendorUploadController(AuthService a){auth=a;}@PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public Map<String,String> upload(@RequestHeader("Authorization") String h,@RequestParam("file") MultipartFile file)throws Exception{auth.actor(h,"VENDOR");if(file.isEmpty()||file.getSize()>5_000_000||file.getContentType()==null||!file.getContentType().startsWith("image/"))throw new IllegalArgumentException("Upload a valid image under 5 MB.");String ext=Optional.ofNullable(file.getOriginalFilename()).filter(n->n.contains(".")).map(n->n.substring(n.lastIndexOf('.'))).orElse(".jpg");Files.createDirectories(Path.of(directory));String name=UUID.randomUUID()+ext;Files.copy(file.getInputStream(),Path.of(directory,name),StandardCopyOption.REPLACE_EXISTING);return Map.of("url","/uploads/"+name);}}
